    6: { level: 6, name: 'Mức 6 (Chuẩn Gốc MITCalc 1.74 - 160pts/răng)', numFlank: 20, numArc: 18, numFillet: 16, ptsPerTooth: 160 },
    7: { level: 7, name: 'Mức 7 (200pts/răng)', numFlank: 25, numArc: 22, numFillet: 20, ptsPerTooth: 200 },
